// Generated by design/build.ts from design/src/tokens.css and panel.css; edit those and run `bun run build`.

/** The panels' stylesheet: the tokens and panel.css, no webfonts. */
export const panelCss: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Take 2 of the design (TEMPRA-53,\n * design/handoff/layout-take-2) set structure and type: neutral greys, a type scale, radii and one soft shadow. Take 3 (TEMPRA-106, design/handoff/layout-take-3) set\n * the frame's sizes, squarer corners and the one colour allowed before the palette: a small warm\n * dot for an agent's recent change. Take 4 (TEMPRA-113, design/handoff/layout-take-4) set the top\n * bar, the wider sidebar and the panel, and gave the dot a second, pulsing state. The palette\n * (TEMPRA-1) changes values here and both the app and the site follow. Light and dark come from\n * the system through light-dark(), or from the account's theme on the root (data-theme).\n */\n:root {\n  color-scheme: light dark;\n\n  /* Color: surfaces */\n  --tempra-color-bg: light-dark(#ffffff, #1b1b1d); /* the page, panels, pills */\n  --tempra-color-ground: light-dark(#f3f3f1, #121214); /* the page under them, inset fills */\n  --tempra-color-hover: light-dark(#e9e9e6, #222225);\n  --tempra-color-selected: light-dark(#e1e1dd, #2a2a2e);\n  --tempra-color-selection: light-dark(#dededa, #3a3a3d);\n\n  /* Color: text, in three steps. Text people read is text or muted, at least 4.5:1 on every\n     surface in light and dark (TEMPRA-132; design/contrast.test.ts). Faint is under that: icons,\n     rules and disabled controls only, never words. */\n  --tempra-color-text: light-dark(#1a1a1b, #ececea);\n  --tempra-color-muted: light-dark(#616165, #9a9a9e);\n  --tempra-color-faint: light-dark(#a3a3a7, #68686c);\n\n  /* Color: lines */\n  --tempra-color-border: light-dark(#e8e8e4, #2a2a2d);\n  --tempra-color-border-strong: light-dark(#d2d2ce, #3c3c40);\n\n  /* Focus (TEMPRA-132): a 2px ring in the text colour on every control focused by keyboard\n     (:focus-visible), until the palette (TEMPRA-1) designs its own */\n  --tempra-focus-ring: 2px solid var(--tempra-color-text);\n  --tempra-focus-offset: 2px;\n\n  /* Color: the change dot (the only colour before the palette) */\n  --tempra-color-agent: light-dark(#e8722a, #f0884a);\n\n  /* Color: chart series (TEMPRA-217). The agreed exception to \"no colour until the palette\"\n     besides the change dot, for a Vega-Lite chart's series and categories only: greys cannot tell\n     two lines apart. Axes, grid and text stay grey. Eight hues in a fixed order, each stepped for\n     its scheme, checked against the page (--tempra-color-bg) with the dataviz validator: adjacent\n     pairs apart under protanopia and deuteranopia, every pair apart to normal vision; three light\n     steps sit under 3:1 on white, so a chart keeps its legend (design/contrast.test.ts). The\n     palette (TEMPRA-1) may replace them. */\n  --tempra-chart-1: light-dark(#2a78d6, #3987e5); /* blue */\n  --tempra-chart-2: light-dark(#eb6834, #d95926); /* orange */\n  --tempra-chart-3: light-dark(#1baf7a, #199e70); /* aqua */\n  --tempra-chart-4: light-dark(#eda100, #c98500); /* yellow */\n  --tempra-chart-5: light-dark(#e87ba4, #d55181); /* magenta */\n  --tempra-chart-6: light-dark(#008300, #008300); /* green */\n  --tempra-chart-7: light-dark(#6250d6, #9085e9); /* violet */\n  --tempra-chart-8: light-dark(#e34948, #e66767); /* red */\n\n  /* Color: a dimmed page behind a sheet or a full-screen view */\n  --tempra-color-scrim: light-dark(rgb(20 20 22 / 0.2), rgb(0 0 0 / 0.5));\n\n  /* Color: the dark frame an attachment is shown on (take 4, board 28), and a mark on it */\n  --tempra-color-frame: light-dark(#0e0e0f, #0a0a0b);\n  --tempra-color-frame-ink: light-dark(#8a8a8e, #8a8a8e);\n\n  /* Color: links are text, underlined in running text (no colour until the palette) */\n  --tempra-color-link: var(--tempra-color-text);\n  --tempra-color-link-visited: var(--tempra-color-text);\n  --tempra-color-code-bg: var(--tempra-color-ground);\n\n  /* Elevation */\n  --tempra-shadow:\n    0 1px 2px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.4)),\n    0 6px 24px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.35));\n\n  /* Type (TEMPRA-108; Inter since 2026-10-23, tempra-dev decisions/one-face.md): one family, Inter\n     (fonts.css), in two roles, and the mono for code. The variable font's optical-size axis is the\n     pairing: the display cut for titles, the text cut for everything read at reading sizes.\n     display: titles and large headings (h1, a view's title, a page's title, the body's h1 and h2,\n       an attachment's name, a compose dialog's name), at the display optical size.\n     text: everything else (chrome, labels, the byline, a page's body, comments, public pages).\n     mono: code, fences, the Markdown view, paths and hashes.\n     The system faces after Inter cover what it has no glyphs for. */\n  --tempra-font-text:\n    \"Inter\", -apple-system, BlinkMacSystemFont, system-ui, \"Segoe UI\", Helvetica, sans-serif;\n  --tempra-font-display: var(--tempra-font-text);\n  --tempra-font-display-settings: \"opsz\" 32; /* Inter's display cut, at any size it is used */\n  --tempra-font-mono: ui-monospace, \"SF Mono\", Menlo, monospace;\n  --tempra-font-size: 14px; /* the app's base text */\n  --tempra-measure: 680px; /* the reader's column, with its padding */\n  --tempra-measure-reader: 34em; /* concept text: about 66 characters at the reading size */\n\n  /* Type scale: the only pixel sizes in the CSS (inside .prose, sizes are em of the reading size) */\n  --tempra-text-initial: 9px; /* an avatar's initials */\n  --tempra-text-label: 11px; /* uppercase labels, marks */\n  --tempra-text-meta: 12px; /* timestamps, small print */\n  --tempra-text-ui: 13px; /* controls, panels, the tree, comments */\n  --tempra-text-name: 15px; /* a library's name, dialog heads, the wordmark */\n  --tempra-text-reader: 17px; /* a concept's body and description, the landing page's lede */\n  --tempra-text-h2: 22px; /* an attachment's name */\n  --tempra-text-page: 28px; /* a view's title (h1); a concept's title on a phone */\n  --tempra-text-title: 36px; /* a concept's title */\n\n  /* Weights: three */\n  --tempra-weight-regular: 400; /* text */\n  --tempra-weight-medium: 500; /* names in rows, a concept's title, the body's h1 and h2 */\n  --tempra-weight-strong: 600; /* the sans's headings, section labels, the wordmark */\n\n  /* Leading: three */\n  --tempra-leading-tight: 1.2; /* titles and headings */\n  --tempra-line-height: 1.5; /* the app's text */\n  --tempra-leading-reader: 1.65; /* reading */\n\n  /* Space */\n  --tempra-space-1: 0.25rem;\n  --tempra-space-2: 0.5rem;\n  --tempra-space-3: 1rem;\n  --tempra-space-4: 2rem;\n  --tempra-gutter: 8px; /* the frame's gutter */\n  --tempra-page-pad: 40px; /* a page's side padding in its column */\n\n  /* The frame (take 4): a top bar across the window, the sidebar, one panel beside a concept.\n     The breakpoints are 1100px (the panel overlays the page) and 900px (the phone layout); a\n     media query cannot read a token, so they are written where they are used. */\n  --tempra-topbar: 60px; /* the top bar */\n  --tempra-sidebar: 264px; /* the sidebar's width */\n  --tempra-panel: 360px; /* a concept's panel (Comments, History, Properties) */\n  --tempra-bar: 52px; /* the phone's top bar */\n  --tempra-drawer: min(82vw, 360px); /* the phone's drawer: about four fifths of the screen */\n  --tempra-sheet: 67dvh; /* a panel as the phone's bottom sheet: about two thirds of the screen */\n  --tempra-row: 30px; /* a sidebar row */\n  --tempra-touch: 44px; /* the least touch target on a phone */\n  --tempra-avatar: 22px;\n  --tempra-avatar-small: 20px;\n  --tempra-dot: 6px; /* an agent's change, a reader's unverified state */\n\n  /* A concept's columns (take 4): the text, centred; on the right its contents, or a panel */\n  --tempra-column-text: 620px;\n  --tempra-contents: 200px;\n  --tempra-figure-wide: 960px; /* a wide figure (`layout=wide`), past the text's measure */\n  --tempra-figure-gap: 12px; /* between a group's images */\n  --tempra-page-width: 760px; /* home, Activity, a folder, the Inbox */\n\n  /* Shape: squarer than take 2 */\n  --tempra-radius: 5px; /* code */\n  --tempra-radius-mark: 3px;\n  --tempra-radius-row: 7px; /* sidebar rows, inputs */\n  --tempra-radius-box: 10px; /* cards, list boxes, threads */\n  --tempra-radius-card: 10px; /* the public pages' sheet, dialogs */\n  --tempra-radius-tile: 6px; /* the library's initial */\n  --tempra-radius-pill: 999px;\n\n  /* Motion: the pulse of the change dot while an agent writes */\n  --tempra-pulse: 1.6s;\n}\n\n/* The account's theme (take 4): the shell puts it on the root; the tokens above follow. */\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n/*\n * Panels: the views an MCP host draws in a chat (TEMPRA-200, the upload panel; tempra-dev\n * app/media, Upload panel). Not part of tempra.css: build.ts puts tokens.css and this file into\n * dist/panel.ts, which the app's build inlines into each panel's one HTML document. A panel sits\n * in the host's conversation, so it takes the host's theme variables (SEP-1865, Theming) where\n * the host gives them, and Tempra's greys where it does not. No webfont: the host's sans, else\n * the system's.\n */\n\n:root {\n  color-scheme: light dark;\n}\n\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n.panel {\n  --panel-text: var(--color-text-primary, var(--tempra-color-text));\n  --panel-muted: var(--color-text-secondary, var(--tempra-color-muted));\n  --panel-surface: var(--color-background-primary, var(--tempra-color-bg));\n  --panel-inset: var(--color-background-secondary, var(--tempra-color-ground));\n  --panel-border: var(--color-border-primary, var(--tempra-color-border-strong));\n  --panel-radius: var(--border-radius-lg, var(--tempra-radius-box));\n  margin: 0;\n  padding: 16px;\n  background: var(--panel-surface);\n  color: var(--panel-text);\n  font-family: var(--font-sans, system-ui, -apple-system, \"Segoe UI\", sans-serif);\n  font-size: 14px;\n  line-height: 1.45;\n}\n\n.panel h1 {\n  margin: 0 0 4px;\n  font-size: 15px;\n  font-weight: 600;\n}\n\n.panel p {\n  margin: 0 0 8px;\n}\n\n.panel .muted {\n  color: var(--panel-muted);\n}\n\n.panel code {\n  font-family: var(--font-mono, ui-monospace, \"SF Mono\", Menlo, monospace);\n  font-size: 0.92em;\n  overflow-wrap: anywhere;\n}\n\n/* The drop area: the file input's label, a dashed box that says what to do. */\n.panel .drop {\n  display: block;\n  margin: 12px 0 8px;\n  padding: 20px 16px;\n  border: 1.5px dashed var(--panel-border);\n  border-radius: var(--panel-radius);\n  background: var(--panel-inset);\n  text-align: center;\n  cursor: pointer;\n}\n\n/* Gone once the file is in: `hidden` over the display rule above. */\n.panel .drop[hidden] {\n  display: none;\n}\n\n.panel .drop .hint {\n  display: block;\n  margin-top: 4px;\n}\n\n.panel .drop.over {\n  border-style: solid;\n  border-color: var(--panel-text);\n}\n\n.panel .drop:focus-within {\n  outline: 2px solid var(--panel-text);\n  outline-offset: 2px;\n}\n\n/* The input stays in the label for the keyboard and screen readers, out of sight. */\n.panel .drop input {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.panel .status {\n  min-height: 1.45em;\n  margin: 8px 0 0;\n}\n\n.panel .actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n  margin-top: 8px;\n}\n\n.panel button {\n  padding: 6px 14px;\n  border: 1px solid var(--panel-border);\n  border-radius: 999px;\n  background: var(--panel-surface);\n  color: var(--panel-text);\n  font: inherit;\n  cursor: pointer;\n}\n\n.panel button.primary {\n  border-color: var(--panel-text);\n  background: var(--panel-text);\n  color: var(--panel-surface);\n}\n\n.panel button:disabled {\n  cursor: default;\n}\n\n.panel button:focus-visible {\n  outline: 2px solid var(--panel-text);\n  outline-offset: 2px;\n}\n\n.panel progress {\n  width: 100%;\n  height: 6px;\n  margin-top: 8px;\n}\n";
